// Publications table (all unique papers, most cited on top).
// Data: `bms_pubs_table`, regenerated by user_provided/python/meta_counts.py.
// Requires: Tabulator (+ SheetJS for the XLSX download).

(function () {
  var table = new Tabulator("#pubs_table", {
    data: bms_pubs_table,
    layout: "fitColumns",
    // "collapse" moves columns that do not fit into the responsive collapse
    // menu instead of hiding them completely (so "Citations" is never lost).
    responsiveLayout: "collapse",
    responsiveCollapse: true,
    tooltips: true,
    placeholder: "No matching publications",
    pagination: "local",
    paginationSize: 50,
    paginationCounter: "rows",
    // most cited papers at the top, exactly as generated
    initialSort: [{ column: "cites", dir: "desc" }],
    columns: [
      { title: "Year", field: "year", width: 60, sorter: "number",
        headerFilter: "input", headerFilterPlaceholder: "year..." },
      // Title is a hyperlink to the paper's DOI URL (doi_url column).
      { title: "Title", field: "title", width: 420,
        formatter: "link",
        formatterParams: { urlField: "doi_url", target: "_blank" },
        headerFilter: "input", headerFilterPlaceholder: "search titles..." },
      { title: "Journal / Publisher", field: "journal", width: 200,
        headerFilter: "input" },
      { title: "Lead Author", field: "author_lead", width: 130,
        headerFilter: "input" },
      { title: "Senior Author", field: "author_anchor", width: 130,
        headerFilter: "input" },
      { title: "Citations", field: "cites", width: 100, sorter: "number",
        hozAlign: "right",
        headerFilter: "number", headerFilterPlaceholder: "min...",
        headerFilterFunc: ">=" },
    ],
  });

  // Download buttons for the current (filtered) view.
  var csvBtn = document.getElementById("download-csv");
  var xlsxBtn = document.getElementById("download-xlsx");
  if (csvBtn) {
    csvBtn.onclick = function () { table.download("csv", "BMSIS_publications.csv"); };
  }
  if (xlsxBtn) {
    xlsxBtn.onclick = function () { table.download("xlsx", "BMSIS_publications.xlsx", { sheetName: "Publications" }); };
  }
})();
